// Shop settings: the only node you edit to adapt this workflow to a new shop.
return [{ json: {
  shop_name: 'Nour Store',            // your shop's name, used in AI answers
  currency: 'DA',
  google_sheet_id: 'PASTE_YOUR_GOOGLE_SHEET_ID',
  owner_telegram_chat_id: 'PASTE_YOUR_TELEGRAM_CHAT_ID',
  whatsapp_phone_number_id: 'PASTE_WHATSAPP_PHONE_NUMBER_ID',
  meta_api_version: 'v21.0',
} }];

// Normalize message: turns a WhatsApp Cloud API or Instagram Messaging webhook
// (or a simple test payload) into one clean shape the rest of the workflow uses.
const raw = $('Incoming message').first().json;
const body = raw.body ?? raw;
const out = [];

function push(m) {
  if (!m.text || !String(m.text).trim()) return;
  out.push({ json: {
    channel: m.channel,                 // whatsapp | instagram | test
    customer_id: String(m.customer_id),
    customer_name: m.customer_name || '',
    business_id: m.business_id || '',   // phone_number_id (WhatsApp) or page/IG id
    message_id: m.message_id || '',
    text: String(m.text).trim(),
    received_at: new Date().toISOString(),
  }});
}

// 1) WhatsApp Cloud API
if (body.object === 'whatsapp_business_account') {
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      const names = Object.fromEntries((v.contacts || []).map(c => [c.wa_id, c.profile?.name || '']));
      for (const msg of v.messages || []) {
        if (msg.type !== 'text') continue;          // images, voice notes etc. are skipped
        push({
          channel: 'whatsapp',
          customer_id: msg.from,
          customer_name: names[msg.from] || '',
          business_id: v.metadata?.phone_number_id,
          message_id: msg.id,
          text: msg.text?.body,
        });
      }
    }
  }
}
// 2) Instagram Messaging (Messenger Platform)
else if (body.object === 'instagram' || body.object === 'page') {
  for (const entry of body.entry || []) {
    for (const ev of entry.messaging || []) {
      if (!ev.message || ev.message.is_echo) continue; // ignore our own replies
      push({
        channel: 'instagram',
        customer_id: ev.sender?.id,
        business_id: ev.recipient?.id,
        message_id: ev.message.mid,
        text: ev.message.text,
      });
    }
  }
}
// 3) Test payload: { "channel": "test", "from": "demo-1", "name": "Amine", "text": "..." }
else if (body.text) {
  push({
    channel: body.channel || 'test',
    customer_id: body.from || 'test-user',
    customer_name: body.name || '',
    message_id: 'test-' + Date.now(),
    text: body.text,
  });
}

// One message per run keeps every downstream step simple; Meta rarely batches.
return out.slice(0, 1);

// Build AI context: one item holding the customer message plus the shop catalog
// and delivery zones, written as short text the AI can read.
const msg = $('Normalize message').first().json;
const products = $('Load catalog').all().map(i => i.json)
  .filter(p => p.sku && String(p.in_stock).toLowerCase() !== 'no');
const zones = $('Load delivery fees').all().map(i => i.json).filter(z => z.wilaya);

const catalogText = products.map(p =>
  `- ${p.sku}: ${p.name} | ${p.price_dzd} DA | sizes: ${p.sizes || 'one size'} | colors: ${p.colors || 'one color'}` +
  (p.aliases ? ` | customers also say: ${p.aliases}` : '')
).join('\n');

const wilayaList = zones.map(z => z.wilaya).join(', ');
const deliveryText = zones.map(z => `${z.wilaya} ${z.fee_dzd} DA`).join(', ');

// A draft this customer left unfinished, so a follow-up like "L, cité 1000 logements" completes it
const pending = $('Find pending order').all().map(i => i.json)
  .filter(r => r.order_id && String(r.customer_id) === String(msg.customer_id) && r.status === 'Waiting for info')
  .pop();
const pendingText = pending
  ? `${pending.items || 'no items yet'}; wilaya: ${pending.wilaya || '?'}; address: ${pending.address || '?'}; phone: ${pending.phone || '?'}; still missing: ${pending.missing || '?'}`
  : 'none';

return [{ json: {
  ...msg,
  catalog_text: catalogText,
  wilaya_list: wilayaList,
  delivery_text: deliveryText,
  pending_order_id: pending ? pending.order_id : '',
  pending_text: pendingText,
  shop_name: $('Shop settings').first().json.shop_name,
}}];

